{"explanation":"A cone and a cylinder with the same circular base area B and height h have volumes V_cone = 1/3 Bh and V_cylinder = Bh. The factor of 1/3 comes from the cone narrowing linearly to a point: at height y above its base, a horizontal slice has area B(1 − y/h)². Integrating those slices from 0 to h gives B∫₀ʰ(1 − y/h)²dy = Bh/3.","manimCode":"const title = new Text({ text: 'Why is a cone one-third of a cylinder?', color: WHITE, fontSize: 32 });
title.moveTo([0, 3.25, 0]);
scene.add(title);

// Side-by-side cross-sections: equal bases and heights.
const cylX = -2.6, coneX = 2.6;
const baseY = -1.8, topY = 1.8;
const r = 1.25;
const cylLeft = new Line({ start: [cylX-r, baseY, 0], end: [cylX-r, topY, 0], color: BLUE });
const cylRight = new Line({ start: [cylX+r, baseY, 0], end: [cylX+r, topY, 0], color: BLUE });
const cylTop = new Line({ start: [cylX-r, topY, 0], end: [cylX+r, topY, 0], color: BLUE });
const cylBase = new Line({ start: [cylX-r, baseY, 0], end: [cylX+r, baseY, 0], color: BLUE });
const coneLeft = new Line({ start: [coneX-r, baseY, 0], end: [coneX, topY, 0], color: ORANGE });
const coneRight = new Line({ start: [coneX+r, baseY, 0], end: [coneX, topY, 0], color: ORANGE });
const coneBase = new Line({ start: [coneX-r, baseY, 0], end: [coneX+r, baseY, 0], color: ORANGE });
scene.add(cylLeft, cylRight, cylTop, cylBase, coneLeft, coneRight, coneBase);

const cylLabel = new Text({ text: 'cylinder', color: BLUE, fontSize: 24 });
cylLabel.moveTo([cylX, 2.25, 0]);
const coneLabel = new Text({ text: 'cone', color: ORANGE, fontSize: 24 });
coneLabel.moveTo([coneX, 2.25, 0]);
const same = new Text({ text: 'same base area B and height h', color: WHITE, fontSize: 22 });
same.moveTo([0, -2.35, 0]);
scene.add(cylLabel, coneLabel, same);

// Show the cone's shrinking horizontal slices and their area.
const sliceY = new ValueTracker(-1.5);
const slice = new Line({ start: [coneX-0.2, -1.5, 0], end: [coneX+0.2, -1.5, 0], color: YELLOW });
slice.addUpdater(() => {
  const y = sliceY.getValue();
  const halfWidth = r * (topY-y)/(topY-baseY);
  slice.setVertices([[coneX-halfWidth, y, 0], [coneX+halfWidth, y, 0]]);
});
scene.add(slice);

const formula = new MathTex({ latex: 'A(y)=B\\left(1-\\frac{y}{h}\\right)^2' });
await formula.waitForRender();
formula.moveTo([0, -3.05, 0]);
scene.add(formula);

const ratio = new MathTex({ latex: 'V_{\\text{cone}}=\\int_0^h A(y)\\,dy=\\frac{1}{3}Bh=\\frac{1}{3}V_{\\text{cylinder}}' });
await ratio.waitForRender();
ratio.moveTo([0, 2.75, 0]);
scene.add(ratio);

const controls = new Controls(scene, { position: 'bottom-right', theme: 'dark', width: 250 });
controls.addSlider({ label: 'Slice height', min: -1.5, max: 1.7, value: -1.5, step: 0.05, onChange: (v) => { sliceY.setValue(v); } });
await scene.wait(999999);"}

